window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dea990d0bca38386"]={"versions": [{"id": "FIG-dea990d0bca38386", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR Adaptive Platform Metamodells / Manifest-Modellierung).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des protokollspezifischen Netzwerk-Deployments für Service-Schnittstellen (<code>ServiceInterface</code>) auf Basis der Data Distribution Service (DDS) Middleware innerhalb von <code>ara::com</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die Zuordnung abstrakter Service-Elemente (Events, Methods, Fields) zu konkreten DDS-Netzwerk-Artefakten (DDS Topics, Topic-Namen, Transportprotokolle) sowie den zugehörigen DDS-Security-Zugriffsregeln (<code>DdsTopicAccessRule</code>) gemäß OMG DDS-Security-Spezifikation.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(abstrakt, Basis: <code>UploadablePackageElement</code>)</em>:</li>\n<li>Generisches Basiselement des Service-Deployments.</li>\n<li>Hält Kompositionen zu generischen Event- und Field-Deployments.</li>\n<li><strong><code>DdsServiceInterfaceDeployment</code></strong> <em>(Spezialisierung von <code>ServiceInterfaceDeployment</code>)</em>:</li>\n<li>Spezifisches Deployment eines Services auf DDS.</li>\n<li>Attribute:</li>\n<li><code>fieldReplyTopicName: String [0..1]</code>: Topic-Name für Antworten auf Field-Operationen (Get/Set-Replies).</li>\n<li><code>fieldRequestTopicName: String [0..1]</code>: Topic-Name für Anfragen auf Field-Operationen (Get/Set-Requests).</li>\n<li><code>methodReplyTopicName: String [0..1]</code>: Topic-Name für RPC-Rückgabewerte (Method Replies via DDS-RPC / Request-Reply Pattern).</li>\n<li><code>methodRequestTopicName: String [0..1]</code>: Topic-Name für RPC-Aufrufe (Method Requests).</li>\n<li><code>serviceInterfaceId: String [0..1]</code>: Eindeutige Kennung des Service-Interface im DDS-Domain-Kontext.</li>\n<li><code>transportProtocol: String [0..*]</code>: Zulässige Transportmechanismen (z. B. UDPv4, UDPv6, Shared Memory).</li>\n<li><strong><code>ServiceEventDeployment</code></strong> <em>(abstrakt, Basis: <code>Identifiable</code>)</em>:</li>\n<li>Generisches Deployment für Service-Events.</li>\n<li><strong><code>DdsEventDeployment</code></strong> <em>(Spezialisierung von <code>ServiceEventDeployment</code>)</em>:</li>\n<li>Bildet ein Service-Event auf ein DDS-Topic ab.</li>\n<li>Attribute:</li>\n<li><code>topicName: String [0..1]</code>: Name des DDS-Topics für das Pub/Sub-Event.</li>\n<li><code>transportProtocol: String [0..*]</code>: Transportbindung für das Event.</li>\n<li><strong><code>ServiceFieldDeployment</code></strong> <em>(abstrakt, Basis: <code>Identifiable</code>)</em>:</li>\n<li>Generisches Deployment für Service-Fields.</li>\n<li><strong><code>DdsFieldDeployment</code></strong> <em>(Spezialisierung von <code>ServiceFieldDeployment</code>)</em>:</li>\n<li>Spezifisches DDS-Deployment für Fields.</li>\n<li>Besitzt eine gerichtete Komposition <code>+notifier [0..1]</code> zu <code>DdsEventDeployment</code> (Realisation des Field-Notifiers über ein DDS-Event-Topic).</li>\n<li><strong><code>DdsTopicAccessRule</code></strong> <em>(Basis: <code>UploadablePackageElement</code>)</em>:</li>\n<li>Sicherheitsrichtlinie für Topic-Zugriffskontrolle und Verschlüsselung gemäß DDS Security (DDS-SEC).</li>\n<li>Attribute:</li>\n<li><code>dataProtectionKind: DdsProtectionKindEnum [0..1]</code>: Sicherheitsstufe für Nutzdaten (Payload).</li>\n<li><code>enableDiscoveryProtection: Boolean [0..1]</code>: Absicherung der Endpoint-Discovery (SPDP/SEDP).</li>\n<li><code>enableLivelinessProtection: Boolean [0..1]</code>: Kryptografische Absicherung von Liveliness-Nachrichten.</li>\n<li><code>enableReadAccessControl: Boolean [0..1]</code>: Erzwingt Autorisierung für DataReader (Subscriber).</li>\n<li><code>enableWriteAccessControl: Boolean [0..1]</code>: Erzwingt Autorisierung für DataWriter (Publisher).</li>\n<li><code>metadataProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzstufe für Metadaten/RTPS-Submessages.</li>\n<li><strong><code>DdsProtectionKindEnum</code></strong> <em>(«enumeration»)</em>:</li>\n<li><code>none</code>: Keine Integritätsprüfung oder Verschlüsselung.</li>\n<li><code>sign</code>: Kryptografische Signatur / MAC (Integrität).</li>\n<li><code>encryptAndSign</code>: Signatur plus Verschlüsselung (Vertraulichkeit + Integrität).</li>\n<li><code>signWithOriginAuthentication</code>: Signatur mit Identitätsnachweis des Senders.</li>\n<li><code>encryptAndSignWithOriginAuthentication</code>: Vollschutz inklusive Quell-Authentifizierung.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><code>ServiceInterfaceDeployment</code> ──◆ <code>+eventDeployment [0..*]</code> ──> <code>ServiceEventDeployment</code></li>\n<li><code>ServiceInterfaceDeployment</code> ──◆ <code>+fieldDeployment [0..*]</code> ──> <code>ServiceFieldDeployment</code></li>\n<li><code>DdsServiceInterfaceDeployment</code> ──> <code>+methodTopicsAccessRule [0..1]</code> ──> <code>DdsTopicAccessRule</code></li>\n<li><code>DdsServiceInterfaceDeployment</code> ──> <code>+fieldTopicsAccessRule [0..1]</code> ──> <code>DdsTopicAccessRule</code></li>\n<li><code>DdsEventDeployment</code> ──> <code>+eventTopicAccessRule [0..1]</code> ──> <code>DdsTopicAccessRule</code></li>\n<li><code>DdsFieldDeployment</code> ──◆ <code>+notifier [0..1]</code> ──> <code>DdsEventDeployment</code></li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (Laufzeitabbildung)</h4>\n<p class=\"fig-p\">Obgleich es sich um ein statisches Metamodell handelt, steuern diese Instanzen das Laufzeitverhalten des <code>ara::com</code>-DDS-Bindings:</p>\n<ul class=\"fig-list\">\n<li><strong>Event-Kommunikation (Pub/Sub):</strong></li>\n<li>Senden eines Events instanziiert einen DDS <code>DataWriter</code> auf dem konfigurierten <code>topicName</code> (<code>DdsEventDeployment</code>).</li>\n<li>Abonnenten erzeugen einen DDS <code>DataReader</code>. Ist <code>eventTopicAccessRule</code> definiert, prüft das DDS-Security-Plugin beim Discovery-Handshake die Berechtigungen (<code>enableReadAccessControl</code> / <code>enableWriteAccessControl</code>) und wendet <code>dataProtectionKind</code> (Signatur/Verschlüsselung) an.</li>\n<li><strong>Methodenaufrufe (RPC via DDS):</strong></li>\n<li>Asynchroner Request/Reply-Kanal: Client sendet Request-Sample über <code>methodRequestTopicName</code>.</li>\n<li>Server verarbeitet den Call und sendet Response über <code>methodReplyTopicName</code> mit Korrelations-ID.</li>\n<li>Autorisierung und Schutz werden zentral über <code>methodTopicsAccessRule</code> parametrisiert.</li>\n<li><strong>Field-Operationen (Get/Set/Notifier):</strong></li>\n<li>Status-Updates laufen asynchron über den referenzierten Notifier (<code>+notifier -&gt; DdsEventDeployment</code>).</li>\n<li>Direkte Lese-/Schreibzugriffe (Getter/Setter) nutzen das über <code>fieldRequestTopicName</code> und <code>fieldReplyTopicName</code> aufgespannte RPC-Muster, gesichert durch <code>fieldTopicsAccessRule</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Generatoren & Manifest-Design (ARXML):</strong></li>\n<li>Die Modellierung in ARXML erfordert für jede <code>ServiceInterface</code>-Instanz mit DDS-Binding zwingend ein <code>DdsServiceInterfaceDeployment</code>.</li>\n<li>Das Nicht-Konfigurieren von Topic-Namen (<code>[0..1]</code>) führt entweder zu Toolchain-Default-Regeln (z. B. Namensbildungsregeln aus Service-/Package-Pfaden) oder zu Validierungsfehlern im Adaptive Code-Generator.</li>\n<li><strong>Stack- und Middleware-Konfiguration:</strong></li>\n<li>Das <code>ara::com</code>-DDS-Binding leitet aus diesen Klassen die QoS-Profile, DDS-Partitions und RTPS-Endpoints ab.</li>\n<li>Wenn <code>transportProtocol</code> mehrfach belegt ist (<code>[0..*]</code>), muss der DDS-Stack Multihoming bzw. hybride Transports (z. B. Shared Memory für intra-Node und UDP für inter-Node) bereitstellen.</li>\n<li><strong>DDS-Security Integration:</strong></li>\n<li>Die Zuweisung einer <code>DdsTopicAccessRule</code> bewirkt, dass der Generator Governance- und Permissions-Dateien (XML/PKCS#7/S/MIME) für das OMG DDS Security Subsystem erzeugt.</li>\n<li>Entwickler müssen sicherstellen, dass bei aktivierten Schutzarten (<code>encryptAndSign<em></code>, <code>sign</em></code>) die entsprechenden Zertifikate und Crypto-Treiber (<code>ara::crypto</code> / HSM) auf der Zielplattform verfügbar und provisioniert sind.</li>\n</ul>"}, {"id": "FIG-14b386693d05da3b", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR Adaptive Platform Metamodells / Manifest-Modellierung).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des protokollspezifischen Netzwerk-Deployments für Service-Schnittstellen (<code>ServiceInterface</code>) auf Basis der Data Distribution Service (DDS) Middleware innerhalb von <code>ara::com</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die Zuordnung abstrakter Service-Elemente (Events, Methods, Fields) zu konkreten DDS-Netzwerk-Artefakten (DDS Topics, Topic-Namen, Transportprotokolle) sowie den zugehörigen DDS-Security-Zugriffsregeln (<code>DdsTopicAccessRule</code>) gemäß OMG DDS-Security-Spezifikation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(abstrakt, Basis: <code>UploadableDesignElement</code>)</em>:</li>\n<li>Generisches Basiselement des Service-Deployments.</li>\n<li>Hält Kompositionen zu generischen Event- und Field-Deployments, annotiert mit den Stereotypen <code>«atpVariation,atpSplitable»</code>.</li>\n<li><strong><code>DdsServiceInterfaceDeployment</code></strong> <em>(Spezialisierung von <code>ServiceInterfaceDeployment</code>)</em>:</li>\n<li>Spezifisches Deployment eines Services auf DDS.</li>\n<li>Attribute:</li>\n<li><code>fieldReplyTopicName: String [0..1]</code>: Topic-Name für Antworten auf Field-Operationen (Get/Set-Replies).</li>\n<li><code>fieldRequestTopicName: String [0..1]</code>: Topic-Name für Anfragen auf Field-Operationen (Get/Set-Requests).</li>\n<li><code>methodReplyTopicName: String [0..1]</code>: Topic-Name für RPC-Rückgabewerte (Method Replies via DDS-RPC / Request-Reply Pattern).</li>\n<li><code>methodRequestTopicName: String [0..1]</code>: Topic-Name für RPC-Aufrufe (Method Requests).</li>\n<li><code>serviceInterfaceId: String [0..1]</code>: Eindeutige Kennung des Service-Interface im DDS-Domain-Kontext.</li>\n<li><code>transportProtocol: String [0..*]</code>: Zulässige Transportmechanismen (z. B. UDPv4, UDPv6, Shared Memory).</li>\n<li><strong><code>ServiceEventDeployment</code></strong> <em>(abstrakt, Basis: <code>Identifiable</code>)</em>:</li>\n<li>Generisches Deployment für Service-Events.</li>\n<li><strong><code>DdsEventDeployment</code></strong> <em>(Spezialisierung von <code>ServiceEventDeployment</code>)</em>:</li>\n<li>Bildet ein Service-Event auf ein DDS-Topic ab.</li>\n<li>Attribute:</li>\n<li><code>topicName: String [0..1]</code>: Name des DDS-Topics für das Pub/Sub-Event.</li>\n<li><code>transportProtocol: String [0..*]</code>: Transportbindung für das Event.</li>\n<li><strong><code>ServiceFieldDeployment</code></strong> <em>(abstrakt, Basis: <code>Identifiable</code>)</em>:</li>\n<li>Generisches Deployment für Service-Fields.</li>\n<li><strong><code>DdsFieldDeployment</code></strong> <em>(Spezialisierung von <code>ServiceFieldDeployment</code>)</em>:</li>\n<li>Spezifisches DDS-Deployment für Fields.</li>\n<li>Besitzt eine gerichtete Komposition <code>+notifier [0..1]</code> zu <code>DdsEventDeployment</code> (Realisation des Field-Notifiers über ein DDS-Event-Topic).</li>\n<li><strong><code>DdsTopicAccessRule</code></strong> <em>(Basis: <code>UploadableDesignElement</code>)</em>:</li>\n<li>Sicherheitsrichtlinie für Topic-Zugriffskontrolle und Verschlüsselung gemäß DDS Security (DDS-SEC).</li>\n<li>Attribute:</li>\n<li><code>dataProtectionKind: DdsProtectionKindEnum [0..1]</code>: Sicherheitsstufe für Nutzdaten (Payload).</li>\n<li><code>enableDiscoveryProtection: Boolean [0..1]</code>: Absicherung der Endpoint-Discovery (SPDP/SEDP).</li>\n<li><code>enableLivelinessProtection: Boolean [0..1]</code>: Kryptografische Absicherung von Liveliness-Nachrichten.</li>\n<li><code>enableReadAccessControl: Boolean [0..1]</code>: Erzwingt Autorisierung für DataReader (Subscriber).</li>\n<li><code>enableWriteAccessControl: Boolean [0..1]</code>: Erzwingt Autorisierung für DataWriter (Publisher).</li>\n<li><code>metadataProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzstufe für Metadaten/RTPS-Submessages.</li>\n<li><strong><code>DdsProtectionKindEnum</code></strong> <em>(«enumeration»)</em>:</li>\n<li><code>none</code>: Keine Integritätsprüfung oder Verschlüsselung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich es sich um ein statisches Metamodell handelt, steuern diese Instanzen das Laufzeitverhalten des <code>ara::com</code>-DDS-Bindings:</p>\n<ul class=\"fig-list\">\n<li><strong>Event-Kommunikation (Pub/Sub):</strong></li>\n<li>Senden eines Events instanziiert einen DDS <code>DataWriter</code> auf dem konfigurierten <code>topicName</code> (<code>DdsEventDeployment</code>).</li>\n<li>Abonnenten erzeugen einen DDS <code>DataReader</code>. Ist <code>eventTopicAccessRule</code> definiert, prüft das DDS-Security-Plugin beim Discovery-Handshake die Berechtigungen (<code>enableReadAccessControl</code> / <code>enableWriteAccessControl</code>) und wendet <code>dataProtectionKind</code> (Signatur/Verschlüsselung) an.</li>\n<li><strong>Methodenaufrufe (RPC via DDS):</strong></li>\n<li>Asynchroner Request/Reply-Kanal: Client sendet Request-Sample über <code>methodRequestTopicName</code>.</li>\n<li>Server verarbeitet den Call und sendet Response über <code>methodReplyTopicName</code> mit Korrelations-ID.</li>\n<li>Autorisierung und Schutz werden zentral über <code>methodTopicsAccessRule</code> parametrisiert.</li>\n<li><strong>Field-Operationen (Get/Set/Notifier):</strong></li>\n<li>Status-Updates laufen asynchron über den referenzierten Notifier (<code>+notifier -&gt; DdsEventDeployment</code>).</li>\n<li>Direkte Lese-/Schreibzugriffe (Getter/Setter) nutzen das über <code>fieldRequestTopicName</code> und <code>fieldReplyTopicName</code> aufgespannte RPC-Muster, gesichert durch <code>fieldTopicsAccessRule</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Einbindung & Variantenmanagement:</strong> <code>ServiceInterfaceDeployment</code> und <code>DdsTopicAccessRule</code> erben von <code>UploadableDesignElement</code> statt von <code>UploadablePackageElement</code>. Die Kompositionsbeziehungen <code>+eventDeployment</code> und <code>+fieldDeployment</code> sind mit <code>«atpVariation,atpSplitable»</code> annotiert, was die Aufteilung über mehrere ARXML-Dateien (<em>splitable</em>) sowie die Steuerung über AUTOSAR-Varianzbedingungen (<em>variation</em>) erlaubt.</li>\n<li><strong>Kardinalitäten und Validierungsregeln:</strong></li>\n<li><code>transportProtocol [0..*]</code> erlaubt die Bindung an mehrere Protokolle (z. B. UDPv4, UDPv6 oder Shared Memory). Fehlt die Angabe, greift der Plattform-Default.</li>\n<li>Topic-Namen (<code>topicName</code>, <code>methodRequestTopicName</code>, <code>methodReplyTopicName</code>, <code>fieldRequestTopicName</code>, <code>fieldReplyTopicName</code>) sind optional <code>[0..1]</code>. Bei Nichtbelegung kommen generatorspezifische Standard-Namenskonventionen zur Anwendung.</li>\n<li>Die Security-Regeln <code>+eventTopicAccessRule</code>, <code>+methodTopicsAccessRule</code> und <code>+fieldTopicsAccessRule</code> besitzen die Multiplizität <code>0..1</code>; ohne Zuordnung greift das ungesicherte Standardverhalten der DDS-Domain.</li>\n<li><strong>Field-Notifier-Bindung:</strong> Ein <code>DdsFieldDeployment</code> kann über die Komposition <code>+notifier [0..1]</code> exakt ein <code>DdsEventDeployment</code> einbinden, um Benachrichtigungen bei Wertänderungen zu übertragen.</li>\n</ul>"}, {"id": "FIG-3d69200af1719819", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR Adaptive Platform Metamodells / Manifest-Modellierung).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des protokollspezifischen Netzwerk-Deployments für Service-Schnittstellen (<code>ServiceInterface</code>) auf Basis der Data Distribution Service (DDS) Middleware innerhalb von <code>ara::com</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die Zuordnung abstrakter Service-Elemente (Events, Methods, Fields) zu konkreten DDS-Netzwerk-Artefakten (DDS Topics, Topic-Namen, Transportprotokolle) sowie den zugehörigen DDS-Security-Zugriffsregeln (<code>DdsTopicAccessRule</code>) gemäß OMG DDS-Security-Spezifikation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(abstrakt, Basis: <code>UploadableDesignElement</code>)</em>:</li>\n<li>Generisches Basiselement des Service-Deployments.</li>\n<li>Hält Kompositionen zu generischen Event- und Field-Deployments, annotiert mit den Stereotypen <code>«atpVariation,atpSplitable»</code>.</li>\n<li><strong><code>DdsServiceInterfaceDeployment</code></strong> <em>(Spezialisierung von <code>ServiceInterfaceDeployment</code>)</em>:</li>\n<li>Spezifisches Deployment eines Services auf DDS.</li>\n<li>Attribute:</li>\n<li><code>fieldReplyTopicName: String [0..1]</code>: Topic-Name für Antworten auf Field-Operationen (Get/Set-Replies).</li>\n<li><code>fieldRequestTopicName: String [0..1]</code>: Topic-Name für Anfragen auf Field-Operationen (Get/Set-Requests).</li>\n<li><code>methodReplyTopicName: String [0..1]</code>: Topic-Name für RPC-Rückgabewerte (Method Replies via DDS-RPC / Request-Reply Pattern).</li>\n<li><code>methodRequestTopicName: String [0..1]</code>: Topic-Name für RPC-Aufrufe (Method Requests).</li>\n<li><code>serviceInterfaceId: String [0..1]</code>: Eindeutige Kennung des Service-Interface im DDS-Domain-Kontext.</li>\n<li><code>transportProtocol: String [0..*]</code>: Zulässige Transportmechanismen (z. B. UDPv4, UDPv6, Shared Memory).</li>\n<li><strong><code>ServiceEventDeployment</code></strong> <em>(abstrakt, Basis: <code>Identifiable</code>)</em>:</li>\n<li>Generisches Deployment für Service-Events.</li>\n<li><strong><code>DdsEventDeployment</code></strong> <em>(Spezialisierung von <code>ServiceEventDeployment</code>)</em>:</li>\n<li>Bildet ein Service-Event auf ein DDS-Topic ab.</li>\n<li>Attribute:</li>\n<li><code>topicName: String [0..1]</code>: Name des DDS-Topics für das Pub/Sub-Event.</li>\n<li><code>transportProtocol: String [0..*]</code>: Transportbindung für das Event.</li>\n<li><strong><code>ServiceFieldDeployment</code></strong> <em>(abstrakt, Basis: <code>Identifiable</code>)</em>:</li>\n<li>Generisches Deployment für Service-Fields.</li>\n<li><strong><code>DdsFieldDeployment</code></strong> <em>(Spezialisierung von <code>ServiceFieldDeployment</code>)</em>:</li>\n<li>Spezifisches DDS-Deployment für Fields.</li>\n<li>Besitzt eine gerichtete Komposition <code>+notifier [0..1]</code> zu <code>DdsEventDeployment</code> (Realisation des Field-Notifiers über ein DDS-Event-Topic).</li>\n<li><strong><code>DdsTopicAccessRule</code></strong> <em>(Basis: <code>UploadableDesignElement</code>)</em>:</li>\n<li>Sicherheitsrichtlinie für Topic-Zugriffskontrolle und Verschlüsselung gemäß DDS Security (DDS-SEC).</li>\n<li>Attribute:</li>\n<li><code>dataProtectionKind: DdsProtectionKindEnum [0..1]</code>: Sicherheitsstufe für Nutzdaten (Payload).</li>\n<li><code>enableDiscoveryProtection: Boolean [0..1]</code>: Absicherung der Endpoint-Discovery (SPDP/SEDP).</li>\n<li><code>enableLivelinessProtection: Boolean [0..1]</code>: Kryptografische Absicherung von Liveliness-Nachrichten.</li>\n<li><code>enableReadAccessControl: Boolean [0..1]</code>: Erzwingt Autorisierung für DataReader (Subscriber).</li>\n<li><code>enableWriteAccessControl: Boolean [0..1]</code>: Erzwingt Autorisierung für DataWriter (Publisher).</li>\n<li><code>metadataProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzstufe für Metadaten/RTPS-Submessages.</li>\n<li><strong><code>DdsProtectionKindEnum</code></strong> <em>(«enumeration»)</em>:</li>\n<li><code>none</code>: Keine Integritätsprüfung oder Verschlüsselung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich es sich um ein statisches Metamodell handelt, steuern diese Instanzen das Laufzeitverhalten des <code>ara::com</code>-DDS-Bindings:</p>\n<ul class=\"fig-list\">\n<li><strong>Event-Kommunikation (Pub/Sub):</strong></li>\n<li>Senden eines Events instanziiert einen DDS <code>DataWriter</code> auf dem konfigurierten <code>topicName</code> (<code>DdsEventDeployment</code>).</li>\n<li>Abonnenten erzeugen einen DDS <code>DataReader</code>. Ist <code>eventTopicAccessRule</code> definiert, prüft das DDS-Security-Plugin beim Discovery-Handshake die Berechtigungen (<code>enableReadAccessControl</code> / <code>enableWriteAccessControl</code>) und wendet <code>dataProtectionKind</code> (Signatur/Verschlüsselung) an.</li>\n<li><strong>Methodenaufrufe (RPC via DDS):</strong></li>\n<li>Asynchroner Request/Reply-Kanal: Client sendet Request-Sample über <code>methodRequestTopicName</code>.</li>\n<li>Server verarbeitet den Call und sendet Response über <code>methodReplyTopicName</code> mit Korrelations-ID.</li>\n<li>Autorisierung und Schutz werden zentral über <code>methodTopicsAccessRule</code> parametrisiert.</li>\n<li><strong>Field-Operationen (Get/Set/Notifier):</strong></li>\n<li>Status-Updates laufen asynchron über den referenzierten Notifier (<code>+notifier -&gt; DdsEventDeployment</code>).</li>\n<li>Direkte Lese-/Schreibzugriffe (Getter/Setter) nutzen das über <code>fieldRequestTopicName</code> und <code>fieldReplyTopicName</code> aufgespannte RPC-Muster, gesichert durch <code>fieldTopicsAccessRule</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Einbindung & Variantenmanagement:</strong> <code>ServiceInterfaceDeployment</code> und <code>DdsTopicAccessRule</code> erben von <code>UploadableDesignElement</code> statt von <code>UploadablePackageElement</code>. Die Kompositionsbeziehungen <code>+eventDeployment</code> und <code>+fieldDeployment</code> sind mit <code>«atpVariation,atpSplitable»</code> annotiert, was die Aufteilung über mehrere ARXML-Dateien (<em>splitable</em>) sowie die Steuerung über AUTOSAR-Varianzbedingungen (<em>variation</em>) erlaubt.</li>\n<li><strong>Kardinalitäten und Validierungsregeln:</strong></li>\n<li><code>transportProtocol [0..*]</code> erlaubt die Bindung an mehrere Protokolle (z. B. UDPv4, UDPv6 oder Shared Memory). Fehlt die Angabe, greift der Plattform-Default.</li>\n<li>Topic-Namen (<code>topicName</code>, <code>methodRequestTopicName</code>, <code>methodReplyTopicName</code>, <code>fieldRequestTopicName</code>, <code>fieldReplyTopicName</code>) sind optional <code>[0..1]</code>. Bei Nichtbelegung kommen generatorspezifische Standard-Namenskonventionen zur Anwendung.</li>\n<li>Die Security-Regeln <code>+eventTopicAccessRule</code>, <code>+methodTopicsAccessRule</code> und <code>+fieldTopicsAccessRule</code> besitzen die Multiplizität <code>0..1</code>; ohne Zuordnung greift das ungesicherte Standardverhalten der DDS-Domain.</li>\n<li><strong>Field-Notifier-Bindung:</strong> Ein <code>DdsFieldDeployment</code> kann über die Komposition <code>+notifier [0..1]</code> exakt ein <code>DdsEventDeployment</code> einbinden, um Benachrichtigungen bei Wertänderungen zu übertragen.</li>\n</ul>"}, {"id": "FIG-f284efb795f82d6b", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR Adaptive Platform Metamodells / Manifest-Modellierung).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des protokollspezifischen Netzwerk-Deployments für Service-Schnittstellen (<code>ServiceInterface</code>) auf Basis der Data Distribution Service (DDS) Middleware innerhalb von <code>ara::com</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die Zuordnung abstrakter Service-Elemente (Events, Methods, Fields) zu konkreten DDS-Netzwerk-Artefakten (DDS Topics, Topic-Namen, Transportprotokolle) sowie den zugehörigen DDS-Security-Zugriffsregeln (<code>DdsTopicAccessRule</code>) gemäß OMG DDS-Security-Spezifikation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(abstrakt, Basis: <code>UploadableDesignElement</code>)</em>:</li>\n<li>Generisches Basiselement des Service-Deployments.</li>\n<li>Hält Kompositionen zu generischen Event- und Field-Deployments, annotiert mit den Stereotypen <code>«atpVariation,atpSplitable»</code>.</li>\n<li><strong><code>DdsServiceInterfaceDeployment</code></strong> <em>(Spezialisierung von <code>ServiceInterfaceDeployment</code>)</em>:</li>\n<li>Spezifisches Deployment eines Services auf DDS.</li>\n<li>Attribute:</li>\n<li><code>fieldReplyTopicName: String [0..1]</code>: Topic-Name für Antworten auf Field-Operationen (Get/Set-Replies).</li>\n<li><code>fieldRequestTopicName: String [0..1]</code>: Topic-Name für Anfragen auf Field-Operationen (Get/Set-Requests).</li>\n<li><code>methodReplyTopicName: String [0..1]</code>: Topic-Name für RPC-Rückgabewerte (Method Replies via DDS-RPC / Request-Reply Pattern).</li>\n<li><code>methodRequestTopicName: String [0..1]</code>: Topic-Name für RPC-Aufrufe (Method Requests).</li>\n<li><code>serviceInterfaceId: String [0..1]</code>: Eindeutige Kennung des Service-Interface im DDS-Domain-Kontext.</li>\n<li><code>transportProtocol: String [0..*]</code>: Zulässige Transportmechanismen (z. B. UDPv4, UDPv6, Shared Memory).</li>\n<li><strong><code>ServiceEventDeployment</code></strong> <em>(abstrakt, Basis: <code>ServiceInterfaceDeploymentElement</code>)</em>:</li>\n<li>Generisches Deployment für Service-Events.</li>\n<li><strong><code>DdsEventDeployment</code></strong> <em>(Spezialisierung von <code>ServiceEventDeployment</code>)</em>:</li>\n<li>Bildet ein Service-Event auf ein DDS-Topic ab.</li>\n<li>Attribute:</li>\n<li><code>topicName: String [0..1]</code>: Name des DDS-Topics für das Pub/Sub-Event.</li>\n<li><code>transportProtocol: String [0..*]</code>: Transportbindung für das Event.</li>\n<li><strong><code>ServiceFieldDeployment</code></strong> <em>(abstrakt, Basis: <code>ServiceInterfaceDeploymentElement</code>)</em>:</li>\n<li>Generisches Deployment für Service-Fields.</li>\n<li><strong><code>DdsFieldDeployment</code></strong> <em>(Spezialisierung von <code>ServiceFieldDeployment</code>)</em>:</li>\n<li>Spezifisches DDS-Deployment für Fields.</li>\n<li>Besitzt eine gerichtete Komposition <code>+notifier [0..1]</code> zu <code>DdsEventDeployment</code> (Realisation des Field-Notifiers über ein DDS-Event-Topic).</li>\n<li><strong><code>DdsTopicAccessRule</code></strong> <em>(Basis: <code>UploadableDesignElement</code>)</em>:</li>\n<li>Sicherheitsrichtlinie für Topic-Zugriffskontrolle und Verschlüsselung gemäß DDS Security (DDS-SEC).</li>\n<li>Attribute:</li>\n<li><code>dataProtectionKind: DdsProtectionKindEnum [0..1]</code>: Sicherheitsstufe für Nutzdaten (Payload).</li>\n<li><code>enableDiscoveryProtection: Boolean [0..1]</code>: Absicherung der Endpoint-Discovery (SPDP/SEDP).</li>\n<li><code>enableLivelinessProtection: Boolean [0..1]</code>: Kryptografische Absicherung von Liveliness-Nachrichten.</li>\n<li><code>enableReadAccessControl: Boolean [0..1]</code>: Erzwingt Autorisierung für DataReader (Subscriber).</li>\n<li><code>enableWriteAccessControl: Boolean [0..1]</code>: Erzwingt Autorisierung für DataWriter (Publisher).</li>\n<li><code>metadataProtectionKind: DdsProtectionKindEnum [0..1]</code>: Schutzstufe für Metadaten/RTPS-Submessages.</li>\n<li><strong><code>DdsProtectionKindEnum</code></strong> <em>(«enumeration»)</em>:</li>\n<li><code>none</code>: Keine Integritätsprüfung oder Verschlüsselung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich es sich um ein statisches Metamodell handelt, steuern diese Instanzen das Laufzeitverhalten des <code>ara::com</code>-DDS-Bindings:</p>\n<ul class=\"fig-list\">\n<li><strong>Event-Kommunikation (Pub/Sub):</strong></li>\n<li>Senden eines Events instanziiert einen DDS <code>DataWriter</code> auf dem konfigurierten <code>topicName</code> (<code>DdsEventDeployment</code>).</li>\n<li>Abonnenten erzeugen einen DDS <code>DataReader</code>. Ist <code>eventTopicAccessRule</code> definiert, prüft das DDS-Security-Plugin beim Discovery-Handshake die Berechtigungen (<code>enableReadAccessControl</code> / <code>enableWriteAccessControl</code>) und wendet <code>dataProtectionKind</code> (Signatur/Verschlüsselung) an.</li>\n<li><strong>Methodenaufrufe (RPC via DDS):</strong></li>\n<li>Asynchroner Request/Reply-Kanal: Client sendet Request-Sample über <code>methodRequestTopicName</code>.</li>\n<li>Server verarbeitet den Call und sendet Response über <code>methodReplyTopicName</code> mit Korrelations-ID.</li>\n<li>Autorisierung und Schutz werden zentral über <code>methodTopicsAccessRule</code> parametrisiert.</li>\n<li><strong>Field-Operationen (Get/Set/Notifier):</strong></li>\n<li>Status-Updates laufen asynchron über den referenzierten Notifier (<code>+notifier -&gt; DdsEventDeployment</code>).</li>\n<li>Direkte Lese-/Schreibzugriffe (Getter/Setter) nutzen das über <code>fieldRequestTopicName</code> und <code>fieldReplyTopicName</code> aufgespannte RPC-Muster, gesichert durch <code>fieldTopicsAccessRule</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Einbindung & Vererbung:</strong> <code>ServiceEventDeployment</code> und <code>ServiceFieldDeployment</code> spezialisieren nun <code>ServiceInterfaceDeploymentElement</code> statt direkt <code>Identifiable</code>. <code>ServiceInterfaceDeployment</code> und <code>DdsTopicAccessRule</code> basieren unverändert auf <code>UploadableDesignElement</code>.</li>\n<li><strong>Variantenmanagement & Kardinalitäten:</strong></li>\n<li>Die Kompositionen <code>+eventDeployment</code> und <code>+fieldDeployment</code> sind unverändert als <code>«atpVariation,atpSplitable»</code> mit Multiplizität <code>0..*</code> definiert.</li>\n<li>Topic-Namen (<code>topicName</code>, <code>methodRequestTopicName</code>, <code>methodReplyTopicName</code>, <code>fieldRequestTopicName</code>, <code>fieldReplyTopicName</code>) bleiben optional <code>[0..1]</code>.</li>\n<li><code>transportProtocol</code> ist weiterhin als <code>[0..*]</code> modelliert.</li>\n<li>Die Security-Regeln <code>+eventTopicAccessRule</code>, <code>+methodTopicsAccessRule</code> und <code>+fieldTopicsAccessRule</code> sind jeweils optional <code>[0..1]</code>.</li>\n<li><strong>Field-Notifier-Bindung:</strong> Ein <code>DdsFieldDeployment</code> bindet unverändert über die Komposition <code>+notifier [0..1]</code> ein <code>DdsEventDeployment</code> ein.</li>\n</ul>"}], "trans": [{"from": "FIG-dea990d0bca38386", "to": "FIG-14b386693d05da3b", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ServiceInterfaceDeployment</code>: Basisklasse von <code>UploadablePackageElement</code> zu <code>UploadableDesignElement</code> geändert.</li>\n<li><code>DdsTopicAccessRule</code>: Basisklasse von <code>UploadablePackageElement</code> zu <code>UploadableDesignElement</code> geändert.</li>\n<li>Komposition <code>+eventDeployment</code>: Stereotyp <code>«atpVariation,atpSplitable»</code> ergänzt.</li>\n<li>Komposition <code>+fieldDeployment</code>: Stereotyp <code>«atpVariation,atpSplitable»</code> ergänzt.</li>\n</ul>"}, {"from": "FIG-14b386693d05da3b", "to": "FIG-3d69200af1719819", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>DdsProtectionKindEnum</code>: UML-Kompartiment-Header <em>literals</em> über den Aufzählungswerten ergänzt.</li>\n</ul>"}, {"from": "FIG-3d69200af1719819", "to": "FIG-f284efb795f82d6b", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ServiceEventDeployment</code>: Basisklasse von <code>Identifiable</code> zu <code>ServiceInterfaceDeploymentElement</code> geändert.</li>\n<li><code>ServiceFieldDeployment</code>: Basisklasse von <code>Identifiable</code> zu <code>ServiceInterfaceDeploymentElement</code> geändert.</li>\n</ul>"}]};
